/** Actual scene counters + optional timer-query result. Unknown hardware metrics stay null. */
export function createSceneMonitor(runtime,{memory=()=>globalThis.performance?.memory?.usedJSHeapSize}={}){const{B,scene,engine}=runtime,caps=rendererCapabilities(runtime),frames=new FrameLog({capacity:600}),sceneMeter=new B.SceneInstrumentation(scene),gpu=caps.gpuTimer?new B.EngineInstrumentation(engine):null;if(gpu)gpu.captureGPUFrameTime=true;let currentMs=null;return{frame(ms){currentMs=ms;frames.add(ms);if(frames.samples.length>=600)frames.samples.splice(0,300);},snapshot({characters=0}={}){const r=frames.report(),heap=memory(),counter=gpu?.gpuFrameTimeCounter,current=counter?.current;return{...r,currentMs,currentFPS:currentMs?1000/currentMs:null,characters,bodies:scene.getPhysicsEngine()?.getBodies().length||0,meshes:scene.getActiveMeshes().length,triangles:runtime.software?runtime.stats().triangles:scene.getActiveIndices()/3,drawCalls:caps.gpu?sceneMeter.drawCallsCounter.current:null,gpuMs:counter?.count>0&&current>0?current/1e6:null,jsHeapMiB:Number.isFinite(heap)?heap/1048576:null,systemRAM:null,gpuVRAM:null};},metadata(){let info=null;try{if(caps.gpu)info=engine.getGlInfo();}catch{}return{engine:'Babylon.js '+B.Engine.Version,physics:'Havok 1.3.14',renderer:caps.renderer,glInfo:info,renderWidth:runtime.canvas?.width||engine.getRenderWidth(),renderHeight:runtime.canvas?.height||engine.getRenderHeight(),capabilities:caps,browser:globalThis.navigator?.userAgent||'Unknown',memoryLabel:'JavaScript heap only; system RAM and GPU VRAM unavailable'};},dispose(){sceneMeter.dispose();gpu?.dispose();}};}
